# ── 1. 首页排版 ──
@row 2
@text letterTitle
@card
  @image charImage
  @text charAlias
@endcard
@endrow

@text innerVoice
@divider
@text chapterTag
@text footerText

# ── 2. 底部触发：真心话浮窗（未删减与正文整体居中） ──
@toggle 1
@spacer 10
@text falseTitle
@card
  @text poemSubTitle
  @text pLine1
  @text pLine2
  @text pLine3
@endcard

# ── 3. 头像触发：短章浮窗 ──
@toggle 2
@spacer 10
@text shortTitle
@card
  @text sLine1
