  @text sLine3
  @text sLine4
  @text sLine5
  @text sLine6
@endcard
@text shortTag
@text shortFoot

# ── 4. 标题触发：下划线极简聊天 ──
@toggle 3
@spacer 10
@text chatTime
@bubbles
  chatLine1:left
  chatLine2:right
  chatLine3:left
  chatLine4:right
  chatLine5:right

